#!/bin/bash

# Read the .env.test file and format it as JSON
JSON_PAYLOAD=$(awk -F '=' '{
    if ($1 ~ /^[A-Za-z_]+$/) {
        key=$1;
        value=$2;
        gsub(/^[ 	]+|[ 	]+$/, "", value);
        printf "\"%s\":\"%s\",", key, value;
    }
}' .env.test | sed 's/,$//' | jq -s "{}" | jq ". += {$(cat)}")

# POST the JSON payload to the endpoint
curl -X POST "http://localhost:47301/api/ci-secret-sync" \
-H "Content-Type: application/json" \
-d "$JSON_PAYLOAD"

